import { apiv3Get } from "@/lib/apiv3";

/**
 * Bir lokasyonun ata zinciri — apiv3 locations/{id}/parents.
 * apiv3 yanıtı { data: [...] }; çağıran düz dizi beklediği için unwrap edilir.
 */
export default async function getLocations(locationId: any) {
    const res = await apiv3Get(`/locations/${locationId}/parents`, { cache: "force-cache" });

    if (!res.ok)
        throw new Error("Failed to fetch data");

    const json = await res.json();
    return json.data ?? [];
}