import type { Metadata } from "next";
import { notFound } from "next/navigation";
import getTourDetail from "@/services/tourDetailService";
import Page from "@/components/tour-detail-page/page";
import getAllTourData from "@/services/getAllTours";
import resolveTourBreadcrumb from "@/services/tour-category-pages/resolveTourBreadcrumb";
import getTourRouteStops from "@/services/tourRouteStops";

export const dynamicParams = true;
export const dynamic = "force-static";

/**
 * Yayın geçidi. Tek doğruluk kaynağı `status`: yalnız "active" turlar gösterilir
 * (draft / pending / revision / inactive gizlenir), custom turlar hiç gösterilmez.
 *
 * `status` yoksa eski `active`/`confirmed` alanlarına düşülür. Veri artık S3 cache'inden
 * değil doğrudan apiv3'ten geliyor (S3 katmanı kaldırıldı), ama ES'te `status` alanı
 * olmayan eski dökümanlar kalmış olabilir — körlemesine `status !== "active"` demek
 * onları 404'e düşürürdü. Tam reindex sonrası bu dal silinebilir; geriye düşüşteki
 * `=== false` de aynı sebeple (alan yoksa engelleme).
 */
function isTourHidden(data: any): boolean {
  if (data?.is_custom_tour) return true;

  return data?.status
    ? data.status !== "active"
    : data?.active === false || !data?.confirmed;
}

export const generateStaticParams = async () => {
  if (process.env.SERVER !== "production") return [];
  const list = await getAllTourData();

  return list.filter((item: any) => !!item.slug);
};

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  try {
    var data = await getTourDetail(params.slug);

    if (isTourHidden(data)) throw new Error("Not publishable tour.");

    return {
      title: data.name + " - TravelShop Booking",
      description:
        "TravelShop Booking is to help you enjoy all the fun of exploring our fascinating world. Click and view " +
        data.name +
        " details.",
      alternates: {
        canonical: "https://travelshopbooking.com/tour/" + params.slug,
      },
    };
  } catch (error) {
    return {};
  }
}

export default async function TourDetailPage({
  params,
}: {
  params: { slug: string };
}) {
  try {
    var data = await getTourDetail(params.slug);

    if (isTourHidden(data)) throw new Error("Not publishable tour.");

    // Rota duraklarının ata zincirinden ilk eşleşen kategori sayfası; hiçbiri
    // tutmazsa yalın "Tour" başlangıcı (bkz. resolveTourBreadcrumb).
    const breadcrumb = (await resolveTourBreadcrumb(data)) ?? [
      { pageTitle: "Tour", pageUrl: "/" },
    ];

    // Route bölümünün zaman çizelgesi: duraklar + ata zincirleri (server'da
    // çözülüyor, hepsi cache'li — bkz. getTourRouteStops).
    const routeStops = await getTourRouteStops(data.routes);

    return (
      <Page tourData={{ ...data, routeStops }} breadcrumb={breadcrumb} />
    );
  } catch (error) {
    return notFound();
  }
}
