export default async function getAllTourData() {

    const res = await fetch(
        `${process.env.NEXT_PUBLIC_APIV3_URL}/tour-list`,
        {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "Content-Language": "en",
                "Content-type": "application/json",
                "X-App-Token": process.env.APIV3_APP_TOKEN ?? "",
            },
            cache: "force-cache"
        }
    );

    if (!res.ok)
        throw new Error("Failed to fetch data");

    return res.json();
}