import getTourCategoryPageDetail from "./getDetail";
import getParentLocations from "./getParentLocations";

export type Breadcrumb = { pageTitle: string; pageUrl: string };

/**
 * Ülke/kıta seviyesi: doğru ama işe yaramaz derecede geniş. Rota duraklarının
 * şehir/ilçe adayları tükenmeden bu seviyeye düşülmez — yoksa bir durağın
 * zinciri "Turkey"e çarpıp diğer durağın şehir sayfasını gölgeler.
 */
const BROAD_TYPES = new Set(["country", "continent"]);

/** Aday üretilirken taranacak rota durağı sayısı (build maliyeti sınırı). */
const MAX_STOPS = 3;

/**
 * Turun rota duraklarından breadcrumb adayı lokasyonlar: her durak için önce
 * durağın kendisi, sonra ata zincirinin TAMAMI (alttan yukarı). Zincir apiv3
 * `/locations/{id}/parents` ile geliyor ve zaten alttan yukarı sıralı.
 *
 * Sonuç iki kademeli: önce spesifik (havaalanı/ilçe/şehir/bölge) adaylar,
 * sonra ülke/kıta adayları.
 */
async function candidateLocations(routes: any[]): Promise<any[]> {
  const specific: any[] = [];
  const broad: any[] = [];
  const seen = new Set<number>();

  for (const stop of routes.slice(0, MAX_STOPS)) {
    if (!stop?.id) continue;

    let chain: any[] = [];
    try {
      chain = await getParentLocations(stop.id);
    } catch (error) {}

    for (const location of [stop, ...chain]) {
      if (!location?.slug || seen.has(location.id)) continue;
      seen.add(location.id);

      (BROAD_TYPES.has(location.type) ? broad : specific).push(location);
    }
  }

  return [...specific, ...broad];
}

/** Bir lokasyon (+ opsiyonel kategori) için kategori sayfası; yoksa null. */
async function fetchPage(destination: string, category?: string) {
  try {
    const page = await getTourCategoryPageDetail({
      params: { destination, category, active: "null" },
    });

    return page?.data ?? null;
  } catch (error) {
    return null;
  }
}

function toBreadcrumb(page: any): Breadcrumb[] {
  const crumb = (item: any) => ({
    pageTitle: item.breadcrumbTitle,
    pageUrl: item.isActive == "1" ? `/${item.pageUrl}` : "/",
  });

  return [...(page.parentCategories ?? []).map(crumb), crumb(page)];
}

/**
 * Tur detayının breadcrumb'ı = turun ilk eşleşen kategori sayfasının zinciri.
 *
 * Eskiden yalnız `routes[0]` ve onun TEK bir ata seviyesi denenirdi; kategori
 * sayfası olmayan bir durakta (ör. "Kayseri Erkilet Airport" → "Kocasinan")
 * zincir orada kesilir, breadcrumb "Tour"a düşerdi — bir üstteki "Kayseri"
 * sayfası hiç sorulmazdı. Artık tüm duraklar ve tüm ata zinciri taranır.
 *
 * Bulunamazsa null döner (çağıran "Tour" fallback'ini kullanır).
 */
export default async function resolveTourBreadcrumb(
  data: any,
): Promise<Breadcrumb[] | null> {
  const routes = Array.isArray(data?.routes) ? data.routes : [];
  const categorySlug = data?.category?.slug;
  // Önce turun kategorisine özel sayfa (ör. .../kayseri-city-sightseeing-tours),
  // yoksa destinasyonun genel sayfası (.../kayseri-tours).
  const categories = categorySlug ? [categorySlug, undefined] : [undefined];

  for (const location of await candidateLocations(routes)) {
    for (const category of categories) {
      const page = await fetchPage(location.slug, category);

      if (page) return toBreadcrumb(page);
    }
  }

  return null;
}
