import getParentLocations from "./tour-category-pages/getParentLocations";

export type RouteCrumb = {
  name: string;
  slug?: string | null;
  type?: string | null;
};

export type RouteStop = {
  id: number | null;
  name: string;
  slug?: string | null;
  lat?: number | null;
  lng?: number | null;
  /** Ancestors, farthest first — ["Europe", "Turkey", "Aydin"] for Kusadasi. */
  parents: RouteCrumb[];
};

/** "dogubeyazit-tour" → "Dogubeyazit Tour" — only used when apiv3 sends no name. */
function titleFromSlug(slug?: string | null): string {
  return (slug ?? "")
    .split("-")
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

/**
 * The tour's journey as the Route section shows it: every stop in travel order,
 * each with its ancestor breadcrumb.
 *
 * Parents are resolved once per UNIQUE location (a round trip visits Istanbul
 * twice but asks the API once) and every lookup is `force-cache`, so the whole
 * catalogue converges on a handful of cached cities. A failed lookup degrades to
 * an empty crumb rather than breaking the page.
 */
export default async function getTourRouteStops(
  routes: any[],
): Promise<RouteStop[]> {
  const ordered = [...(routes ?? [])]
    .filter((r) => r && (r.name || r.slug))
    .sort(
      (a, b) => (a.pivot?.order_sort ?? 0) - (b.pivot?.order_sort ?? 0),
    );

  if (ordered.length === 0) return [];

  const ids: number[] = Array.from(
    new Set(ordered.map((r) => r.id).filter(Boolean)),
  );

  const resolved = await Promise.all(
    ids.map(async (id): Promise<[number, RouteCrumb[]]> => {
      try {
        const parents = await getParentLocations(id);
        // apiv3 returns nearest parent first; a breadcrumb reads the other way.
        return [
          id,
          [...parents]
            .reverse()
            .map((p: any) => ({
              name: p?.name,
              slug: p?.slug ?? null,
              type: p?.type ?? null,
            }))
            .filter((p: RouteCrumb) => !!p.name),
        ];
      } catch {
        return [id, []];
      }
    }),
  );

  const byId = new Map<number, RouteCrumb[]>(resolved);

  return ordered.map((r) => ({
    id: r.id ?? null,
    name: r.name || titleFromSlug(r.slug),
    slug: r.slug ?? null,
    lat: r.lat ?? null,
    lng: r.lng ?? null,
    parents: byId.get(r.id) ?? [],
  }));
}
